60	    /// Probe the `/health` endpoint and return the reported capabilities.
61	    ///
62	    /// Returns an empty vec on any error (server down, old version, etc.).
63	    pub async fn capabilities(&self) -> Vec<String> {
64	        let url = format!("{}/health", self.base_url);
65	        let Ok(resp) = self.http.get(&url).send().await else {
66	            return Vec::new();
67	        };
68	        let Ok(json) = resp.json::<serde_json::Value>().await else {
69	            return Vec::new();
70	        };
71	        json.get("capabilities")
72	            .and_then(|v| v.as_array())
73	            .map(|caps| {
74	                caps.iter()
75	                    .filter_map(|c| c.as_str().map(String::from))
76	                    .collect()
77	            })
78	            .unwrap_or_default()
79	    }
