81	    /// Generate text embeddings via the local MLX server.
82	    pub async fn embed(
83	        &self,
84	        model: &str,
85	        texts: &[String],
86	        task: EmbedTask,
87	    ) -> Result<EmbeddingResponse, MlxError> {
88	        let url = format!("{}/v1/embeddings", self.base_url);
89	        let request = TextEmbeddingRequest {
90	            model,
91	            input: texts,
92	            task,
93	        };
94	        let resp = self.http.post(&url).json(&request).send().await?;
95	        self.handle_response(resp).await
96	    }
