136	    async fn handle_response<T: serde::de::DeserializeOwned>(
137	        &self,
138	        resp: Response,
139	    ) -> Result<T, MlxError> {
140	        let status = resp.status();
141	        if !status.is_success() {
142	            let detail = resp.text().await.unwrap_or_default();
143	            return Err(MlxError::ServerError {
144	                status: status.as_u16(),
145	                detail,
146	            });
147	        }
148	        Ok(resp.json().await?)
149	    }
