717	// ---------------------------------------------------------------------------
718	// Embedding provider abstraction
719	// ---------------------------------------------------------------------------
720	
721	/// A unified embedding provider that wraps either OpenRouter or a local MLX
722	/// server.  Both return `EmbeddingResponse` in the same OpenAI-compatible
723	/// format.
724	#[derive(Clone)]
725	enum EmbedProvider {
726	    OpenRouter(Arc<OpenRouterClient>),
727	    Mlx(Arc<MlxClient>),
728	}
729	
730	impl EmbedProvider {
731	    /// Embed `texts` for `task`, returning one vector per text in input order.
732	    ///
733	    /// Only the MLX server takes a task; OpenRouter embeds the text as given.
734	    async fn embed(
735	        &self,
736	        model: &str,
737	        texts: &[String],
738	        task: EmbedTask,
739	    ) -> Result<Vec<Vec<f64>>, Arc<String>> {
740	        let resp = match self {
741	            Self::OpenRouter(client) => client
742	                .embed(model, texts)
743	                .await
744	                .map_err(|e| Arc::new(e.to_string())),
745	            Self::Mlx(client) => client
746	                .embed(model, texts, task)
747	                .await
748	                .map_err(|e| Arc::new(e.to_string())),
749	        }?;
750	        ordered_embeddings(resp, texts.len())
751	    }
752	
753	    /// Embed a search query and the documents to score against it.
754	    ///
755	    /// Queries and documents take different task prompts, so the MLX server
756	    /// gets one request for each. OpenRouter has no task prompts and takes
757	    /// both in a single batch.
758	    async fn embed_query_and_documents(
759	        &self,
760	        model: &str,
761	        query: &str,
762	        documents: &[String],
763	    ) -> Result<(Vec<f64>, Vec<Vec<f64>>), Arc<String>> {
764	        let query = [query.to_string()];
765	        let (mut query_embs, doc_embs) = match self {
766	            Self::Mlx(_) => tokio::try_join!(
767	                self.embed(model, &query, EmbedTask::SearchQuery),
768	                self.embed(model, documents, EmbedTask::Document),
769	            )?,
770	            Self::OpenRouter(_) => {
771	                let texts: Vec<String> = query.iter().chain(documents).cloned().collect();
772	                let mut embs = self.embed(model, &texts, EmbedTask::Document).await?;
773	                let doc_embs = embs.split_off(1);
774	                (embs, doc_embs)
775	            }
776	        };
777	        let query_emb = query_embs
778	            .pop()
779	            .ok_or_else(|| Arc::new("No embedding returned for the query".to_string()))?;
780	        Ok((query_emb, doc_embs))
781	    }
782	}
