784	/// Unpack an embedding response into vectors in input order, checking that
785	/// the provider returned one per input.
786	fn ordered_embeddings(
787	    resp: EmbeddingResponse,
788	    expected: usize,
789	) -> Result<Vec<Vec<f64>>, Arc<String>> {
790	    if resp.data.len() != expected {
791	        return Err(Arc::new(format!(
792	            "Expected {expected} embeddings, got {}",
793	            resp.data.len()
794	        )));
795	    }
796	    let mut data = resp.data;
797	    data.sort_by_key(|d| d.index);
798	    Ok(data.into_iter().map(|d| d.embedding).collect())
799	}
